class Graph:
    def __init__(self):
        self.adj = {}

    def add_edge(self, u, v):
        self.adj.setdefault(u, []).append(v)
        self.adj.setdefault(v, []).append(u)

    def neighbors(self, u):
        return list(self.adj.get(u, []))

def dfs(graph, start):
    visited = []
    seen = set()
    stack = [start]
    while stack:
        node = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        visited.append(node)
        for nbr in reversed(graph.get(node, [])):
            if nbr not in seen:
                stack.append(nbr)
    return visited

