from collections import deque

def bfs(graph, start):
    visited = []
    seen = {start}
    q = deque([start])
    while q:
        node = q.popleft()
        visited.append(node)
        for nbr in graph.get(node, []):
            if nbr not in seen:
                seen.add(nbr)
                q.append(nbr)
    return visited

from collections import deque

def shortest_path_length(graph, start, goal):
    if start == goal:
        return 0
    seen = {start}
    q = deque([(start, 0)])
    while q:
        node, dist = q.popleft()
        for nbr in graph.get(node, []):
            if nbr in seen:
                continue
            if nbr == goal:
                return dist + 1
            seen.add(nbr)
            q.append((nbr, dist + 1))
    return -1

from collections import deque

def is_connected(graph):
    if not graph:
        return True
    start = next(iter(graph))
    seen = {start}
    q = deque([start])
    while q:
        node = q.popleft()
        for nbr in graph.get(node, []):
            if nbr not in seen:
                seen.add(nbr)
                q.append(nbr)
    return len(seen) == len(graph)
